  "cons.note.icpTouch": "Puntos de contacto, no leads: el número grande es cuántos salieron, el chico cuántas personas distintas los recibieron. Las llamadas vienen de la tabla de calls, no de la secuencia — por eso un flow puede mostrar llamadas sin tener un step de llamada.",
  "cons.note.icpMatrix": "Leé una celda así: de los leads que este ICP alcanzó por ese canal, cuántos respondieron. Un lead alcanzado por dos canales se cuenta en ambos, así que las columnas no suman el total del ICP.",
  "cons.icp.worthTitle": "{name} tiene la mejor tasa de respuesta",
  "cons.icp.worthNone": "Ningún ICP envió en este período",
  "cons.icp.worthFact": "{name}: {replies} de {contacted} contactados respondieron ({rate}%), sobre {touch} puntos de contacto.",
  "cons.note.campaigns": "{n} flows enviaron en este período, agrupados por ICP para que las tasas dentro de un grupo sean comparables. Por debajo de {floor} leads contactados un flow muestra conteos pero no porcentaje.",
  "cons.note.flowDetail": "Todo acá se mide sobre la cohorte propia del flow — los leads que contactó en la ventana — así el detalle reconcilia con la fila de arriba. Los días medianos van del primer mensaje del flow a ese lead hasta su primera respuesta. Las llamadas se atan por el lead, no por un step.",
  "cons.note.steps": "Cada step muestra el canal que realmente usó. 'Respondió en el step 2' no significa nada hasta que sepas que el step 2 era un DM.",
  "cons.note.campaignsRemoved": "Won y Lost no se muestran. El status won nunca se seteó en ningún flow, y lost mezcla una respuesta negativa con un lead cerrado a mano — dos eventos distintos bajo un mismo número.",
  "cons.note.whatsapp": "WhatsApp está cableado end-to-end pero no envió nada en este período, así que no tiene card en vez de una card de ceros.",
  "cons.note.headToHead": "Solo LinkedIn DM y Email se rankean cabeza a cabeza: misma medición, misma ventana, misma unidad — leads que respondieron sobre leads alcanzados. La aceptación de invitaciones y la tasa de contacto confirmado son números reales con bases reales, pero miden eventos distintos.",
  "cons.channel.worthTitle": "Los dos canales comparables están muy separados",
